public class Solution {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int[] a = parse(sc.nextLine());
        int[] b = parse(sc.nextLine());
        StringBuilder sb = new StringBuilder();
        int i = 0, j = 0;
        while (i < a.length && j < b.length) sb.append(a[i] <= b[j] ? a[i++] : b[j++]).append(' ');
        while (i < a.length) sb.append(a[i++]).append(' ');
        while (j < b.length) sb.append(b[j++]).append(' ');
        System.out.println(sb.toString().trim());
    }
    static int[] parse(String line) {
        if (line == null || line.isEmpty()) return new int[0];
        String[] parts = line.trim().split("\\s+");
        int[] r = new int[parts.length];
        for (int k = 0; k < parts.length; k++) r[k] = Integer.parseInt(parts[k]);
        return r;
    }
}

