        if (c == '(' || c == '[' || c == '{') st.push(c);
        else {
            if (st.empty()) { cout << "false\n"; return 0; }
            char t = st.top(); st.pop();
            if ((c == ')' && t != '(') || (c == ']' && t != '[') || (c == '}' && t != '{')) { cout << "false\n"; return 0; }
        }
    }
    cout << (st.empty() ? "true" : "false") << "\n";
